/**
 * The files committed in `packages/watchlist/fixtures/` (C77.5): each is generated by this module
 * from fixed seeds, and `fixture-files.test.ts` fails when a committed file differs from what the
 * generators write today. Regenerate them with
 * `OPENVERIFY_WRITE_FIXTURES=1 pnpm --filter @openverify/watchlist exec vitest run src/testing/fixture-files.test.ts`,
 * then `pnpm exec prettier --write packages/watchlist/fixtures`.
 */
import { normalisedImportText } from './normalised.js';
import { openverifySandboxList, openverifySandboxPepList } from './sandbox.js';
import {
  SANDBOX_PEP_CLASS_QIDS,
  pepImportAnswers,
  pepSparqlAnswer,
  sandboxPepSparqlFacts,
  sparqlResultsText,
} from './sparql.js';

/** The fixtures folder, beside the package's `src`. */
export const FIXTURES_DIRECTORY = new URL('../../fixtures/', import.meta.url);

/** Every committed fixture: its file name and its text. */
export function fixtureFiles(): Readonly<Record<string, string>> {
  return {
    'openverify-sandbox.json': normalisedImportText(openverifySandboxList(1)),
    'openverify-sandbox.v2.json': normalisedImportText(openverifySandboxList(2)),
    'openverify-sandbox.v3.json': normalisedImportText(openverifySandboxList(3)),
    'openverify-sandbox.v4.json': normalisedImportText(openverifySandboxList(4)),
    'openverify-sandbox-pep.json': normalisedImportText(openverifySandboxPepList()),
    'wikidata-pep.synthetic.sparql.json': sparqlResultsText(
      pepSparqlAnswer(sandboxPepSparqlFacts()),
    ),
    // C89.2: what `watchlists:sync --import <file> --source wikidata-pep` reads.
    'wikidata-pep.synthetic.answers.json': `${JSON.stringify(
      pepImportAnswers(sandboxPepSparqlFacts(SANDBOX_PEP_CLASS_QIDS)),
      null,
      2,
    )}\n`,
  };
}
